def straight_high(ranks: list[str]) -> str | None:
    """Return the highest rank of a straight if the hand is a straight, else None."""
    # Map each rank character to an integer 0-12
    rank_to_val = {c: i for i, c in enumerate("23456789TJQKA")}
    values = [rank_to_val[r] for r in ranks]

    # A straight must have 5 distinct ranks
    if len(set(values)) != 5:
        return None

    sorted_vals = sorted(values)

    # Check normal consecutive sequence
    if all(sorted_vals[i] - sorted_vals[i - 1] == 1 for i in range(1, 5)):
        return "23456789TJQKA"[sorted_vals[-1]]

    # Check wheel straight (A-2-3-4-5)
    if sorted_vals == [0, 1, 2, 3, 12]:
        return "5"  # highest card is 5 in the wheel

    return None
